-- supabase/scholarship_enrichment_batch20_2026-10-28.sql
-- Enrichment Batch 20 (2026-10-28), Denmark state-scheme additions following cleanup pass 113,
-- each verified first-hand on official pages the same day:
--   972 Danish State Tuition Fee Waivers and Scholarships at Roskilde University (rel 10)
--   973 Danish Government Scholarship at the University of Southern Denmark       (rel 10)
-- sources 3106 (RUC scheme page) / 3107 (SDU scholarships page); links 972->3106, 973->3107.
-- No university_scholarships rows and university_id NULL on both: no Roskilde or SDU
-- records exist in the universities table yet (create/backlink recorded as a future task).
-- Effect (verified 2026-10-28): active 543 (was 541), retired 178, active rel-4 28,
-- future deadlines 191. Replay: timestamps use now(); run against the post-pass-113 state.

INSERT INTO scholarships (id, title, provider, country, coverage_type, amount_usd_value, deadline, deadline_date, deadline_type, deadline_range_start, deadline_range_end, degree_levels, eligible_majors, eligible_countries, min_gpa, min_ielts, financial_need_based, merit_based, description, requirements, website_url, source_url, application_url, recurrence, application_status, verification_status, source_reliability, is_active, last_verified_at, last_updated_at, notes, university_id, award_amount, award_currency, award_period, award_basis, living_allowance, funding_type, tuition_coverage, english_requirements, required_documents, expected_opening_period, expected_deadline_period, rounds) VALUES (972, 'Danish State Tuition Fee Waivers and Scholarships at Roskilde University', 'Roskilde University', 'Denmark', 'Tuition Waiver', 0, 'Once a year, for the September entry only: the non-EU/EEA application round on DANS opens 15 December 2026 and the deadline for fee-paying non-EU/EEA applicants is 15 January 2027 (23:59 CET) - your motivational letter and CV must be uploaded as part of the admission application at submission, otherwise you will not be considered for a waiver and scholarship. Late applications are not accepted; enrolled students cannot apply in a later semester.', '2027-01-15', 'fixed', NULL, NULL, $j$["Master's"]$j$, $j$["Selected master's programmes at Roskilde University (the university chooses the list before each admission round; for the September 2026 entry: Master in Media and Communication, Master in Environmental Science, Master in Nordic Urban Planning Studies, Master in Computer Science - the September 2027 list is published on the scheme page right before the round opens on 15 December 2026)"]$j$, $j$["Non-EU/EEA citizens from countries outside the EU/EEA who are required to pay tuition fees at Roskilde University"]$j$, NULL, NULL, false, true, $desc$Roskilde University offers a limited number of Danish state tuition fee waivers and scholarships for selected master's programmes to highly talented students who come from countries outside the EU/EEA and are required to pay tuition fees. The package has two parts: a tuition fee waiver, and a scholarship of DKK 7,800 per month meant to cover living expenses in Denmark; together they run for a maximum of 22 months for programmes starting in September. The waivers and scholarships are distributed only once a year, for the September entry, and only on the specific programmes the university selects before each admission round (for September 2026: Media and Communication, Environmental Science, Nordic Urban Planning Studies and Computer Science; the list for September 2027 is published on the scheme page right before the non-EU/EEA application round opens on 15 December 2026). Being eligible to apply does not guarantee an award - applicants are ranked on academic performance, the motivational letter and work experience (family or social background is not taken into account), and the number is limited. Unlike some sister schemes, consideration is NOT automatic: you apply by uploading a motivational letter and a CV outlining your academic and occupational background into your online application for admission, and both documents must be there when you submit the application or you will not be considered at all. It is also a one-shot door: enrolled students cannot apply or re-apply in a later semester. To keep the waiver and scholarship you must follow the study plan and must not be delayed in your studies. The binding deadline for fee-paying non-EU/EEA applicants is 15 January (23:59 CET) for the 1 September start; the DANS application system is available one month before the deadline.$desc$, $req$You must be a non-EU/EEA citizen required to pay tuition fees and apply to one of the master's programmes that offer scholarships in that round (the list is fixed before each round; check the scheme page when the round opens on 15 December). The application for the waiver and scholarship is the motivational letter plus CV uploaded to the online admission application within the deadline - if they are missing at submission, the university will not consider you, and there is no way to apply later as an enrolled student. Ranking is merit-based on three elements: academic performance, the motivational letter and work experience; family or social background is explicitly not considered. Duration is capped at 22 months and retention requires following the study plan without delay. The September-only rhythm means a single annual chance; late applications are not accepted and applying well in advance is strongly recommended (technical problems possible). No numeric GPA cutoff or scholarship-level IELTS figure is published (English documentation belongs to programme admission), so min_gpa/min_ielts are not recorded.$req$, 'https://ruc.dk/en/step-5-tuition-fees-tuition-fee-waivers-and-scholarships', 'https://ruc.dk/en/step-5-tuition-fees-tuition-fee-waivers-and-scholarships', 'https://ruc.dk/en/admission-masters-programmes', 'annual', 'upcoming', 'verified', 10, true, now(), now(), $note$ADDED 2026-10-28 (enrichment batch 20) from Roskilde University's official pages fetched the same day - 'Step 5: Tuition Fees, Tuition Fee Waivers and Scholarships' (limited number of Danish state tuition fee waivers and scholarships for selected master's programmes, for highly talented students from outside the EU/EEA required to pay tuition fees; distributed once a year for the September entry; maximum length 22 months for September-starting programmes; scholarship of DKK 7,800 per month meant to cover living expenses in Denmark; holders must follow the study plan and not be delayed; eligibility: non-EU/EEA citizen required to pay fees applying to a scholarship-offering programme; ranking on academic performance, motivational letter and work experience, family/social background not considered; programme list selected before each round - September 2026: Media and Communication, Environmental Science, Nordic Urban Planning Studies, Computer Science; the September 2027 list expected on the page right before the non-EU/EEA application round opens on 15 December 2026; application = motivational letter and CV uploaded with the admission application at submission or no consideration; enrolled students cannot apply/re-apply later) and 'Step 1: Application Deadlines' (master's start once a year on 1 September; DANS system available one month before the deadline; non-EU/EEA citizens required to pay tuition fees: 15 January, 23:59 CET; late applications not accepted). A same-day search-index read of RUC's 'Step 3: Required Documentation' page additionally shows a receipt for a paid application fee of EUR 165 among the non-EU/EEA documents. The scheme is Roskilde's administration of the same Danish state scholarship family as record 413 (Aarhus), with materially different mechanics (letter-based, fixed monthly scholarship), and Roskilde had no catalogue record before this batch. Award stored as 7800 DKK/'month'/'fixed' - the published living-expense scholarship; the waiver component follows each programme's tuition fee and is described in funding_type (the page does not state a waiver percentage, so none is claimed). deadline_date 2027-01-15 ('fixed') is the next fee-paying non-EU/EEA deadline for the September 2027 entry; status 'upcoming' because the round opens only on 15 December 2026. min_gpa/min_ielts NULL. university_id intentionally NULL: no Roskilde University record exists in the universities table yet - create/backlink recorded as a future task; no university_scholarships row. A dedicated verified source was inserted for the scheme page.$note$, NULL, 7800, 'DKK', 'month', 'fixed', NULL, 'Tuition fee waiver plus a living-expense scholarship of DKK 7,800 per month, together for a maximum of 22 months (September entry); only on the programmes selected for the round; you must apply with a motivational letter + CV at admission submission and stay on the study plan to keep it', 'The tuition fee is waived for the scholarship period of max 22 months (the waiver value follows the programme fee; the scheme page states no percentage); the DKK 7,800/month scholarship is for living expenses and is separate from the waiver.', 'No scholarship-level IELTS figure; English documentation belongs to each master''s programme''s admission requirements.', $j$["Online admission application via DANS by 15 January (23:59 CET) for fee-paying non-EU/EEA applicants (September start; system opens one month earlier, on 15 December)", "Motivational letter outlining your qualifications for the master's programme - uploaded with the application at submission, otherwise no scholarship consideration", "CV outlining your academic and occupational background, uploaded at submission", "Application-fee receipt and the programme's admission documents (a Statement of Academic Interest is also required for English-taught master's programmes)"]$j$, NULL, NULL, $json$[{"round": "September 2027 entry", "opens": "2026-12-15", "deadline": "2027-01-15", "status": "upcoming"}, {"pattern": "Annual, September entry only: programme list published just before the non-EU/EEA round opens in mid-December; apply with motivational letter + CV by 15 January; award = waiver + DKK 7,800/month for max 22 months"}]$json$);

INSERT INTO scholarships (id, title, provider, country, coverage_type, amount_usd_value, deadline, deadline_date, deadline_type, deadline_range_start, deadline_range_end, degree_levels, eligible_majors, eligible_countries, min_gpa, min_ielts, financial_need_based, merit_based, description, requirements, website_url, source_url, application_url, recurrence, application_status, verification_status, source_reliability, is_active, last_verified_at, last_updated_at, notes, university_id, award_amount, award_currency, award_period, award_basis, living_allowance, funding_type, tuition_coverage, english_requirements, required_documents, expected_opening_period, expected_deadline_period, rounds) VALUES (973, 'Danish Government Scholarship at the University of Southern Denmark', 'University of Southern Denmark', 'Denmark', 'Full Tuition Waiver', 0, 'No separate scholarship application: apply for one of the listed SDU programmes by 1 February (master''s, with the complete documentation at submission - even if you hold a Danish residence permit; interviews normally 19-27 February) or by 15 March (bachelor''s; uniTEST high scorers are invited to interviews in early June). Next master''s gate: 1 February 2027; next bachelor''s gate: 15 March 2027.', '2027-02-01', 'fixed', NULL, NULL, $j$["Bachelor's", "Master's"]$j$, $j$["Named programmes at SDU's Sønderborg and Vejle campuses only. For admissions up to and including 2027 - MSc (Sønderborg): Engineering Physics, Electrical Engineering, Mechanical Engineering, Mechatronics, Software Engineering; BSc (Vejle): Artificial Intelligence, Computer Science, Interactive Technology Engineering, Software Engineering. From 2028 onwards four MSc programmes at Vejle are added (Artificial Intelligence, Computer Science, Software Engineering, Interactive Technology Engineering) and the BSc list narrows to Artificial Intelligence and Computer Science"]$j$, $j$["Non-EU/EEA citizens enrolling in the listed programmes; students eligible for the Danish State Educational Grant and Loan Scheme (SU) are NOT eligible for this scholarship"]$j$, NULL, NULL, false, true, $desc$The University of Southern Denmark offers the Danish Government Scholarship - a limited number of government scholarships for highly qualified applicants, in recognition of the important investment that overseas students make during their education - but only on named programmes at its Sønderborg and Vejle campuses. The scholarship is a full tuition fee waiver covering the standard duration of the programme (two years for MSc programmes and three years for BSc programmes); the waiver covers 30 ECTS per semester, and credits beyond that in a semester are not covered. One exclusion cuts across everything: students who are eligible for support under the Danish State Educational Grant and Loan Scheme (SU) cannot receive this scholarship. The programme list is fixed and published in advance: for admissions up to and including 2027 it is five engineering MSc programmes at Sønderborg (Engineering Physics, Electrical Engineering, Mechanical Engineering, Mechatronics, Software Engineering) and four BSc programmes at Vejle (Artificial Intelligence, Computer Science, Interactive Technology Engineering, Software Engineering); from 2028 the Vejle portfolio gains four MSc programmes while the bachelor list narrows to Artificial Intelligence and Computer Science. There is no separate scholarship application at either level - you simply apply for admission - but each level has its own selection contest. Bachelor's applicants must apply by 15 March; those with the highest scores in the online admission test (uniTEST) are invited (at short notice in late May) to an online interview in early June consisting of a few mathematical questions and a brief motivation talk, and the award rests on test plus interview. Master's applicants must apply by 1 February with the complete documentation already at submission - deposit fee receipt, official bachelor's transcripts and diploma, verified course descriptions, any self-assessment form, and proof of English proficiency - and, if they applied to several SDU programmes, are only considered if the eligible master's is their highest priority; selection rests on the bachelor's GPA and an online interview (invitations at short notice after 15 February, interviews normally 19-27 February, a few technical questions, no specific preparation needed). To keep the scholarship you must show satisfactory academic progress every semester - normally successful completion of 30 ECTS per semester - or the funding may be discontinued for the following semester.$desc$, $req$You must be a non-EU/EEA citizen enrolling in one of the listed Sønderborg (MSc) or Vejle (BSc, and from 2028 also MSc) programmes, and you must NOT be eligible for SU. No separate application exists, but the consideration gates are strict. Bachelor's: application for admission no later than 15 March; selection by uniTEST result (top scorers invited) plus an online interview in early June (invitation by email at short notice in late May; if you applied for several eligible programmes you get one interview only; a few mathematical questions and a motivation talk, no specific preparation required). Master's: application no later than 1 February - this applies even if you hold a Danish residence permit - with ALL necessary documentation present at submission (the application must not leave SDU needing to ask for more): application deposit fee receipt; official bachelor's transcripts and diploma in English, Danish, Swedish or Norwegian including grades and ECTS/units per course; verified course descriptions; self-assessment form if the programme has one; proof of English proficiency - everything uploaded to the online application (documents sent by email are not accepted). If you applied for more than one SDU programme, you are only considered if the eligible master's programme is your highest priority. Selection: bachelor's GPA plus online interview (invitations after 15 February; interviews normally 19-27 February; a few technical questions related to the entry requirements). Retention: satisfactory progress each semester, normally 30 ECTS completed per semester, else the scholarship may be discontinued for the following semester; the waiver covers only 30 ECTS per semester. No single numeric GPA cutoff and no scholarship-level IELTS figure are published (the GPA competes comparatively; English proof follows admission rules), so min_gpa/min_ielts are not recorded.$req$, 'https://www.sdu.dk/en/uddannelse/fees_and_funding/scholarships', 'https://www.sdu.dk/en/uddannelse/fees_and_funding/scholarships', 'https://www.sdu.dk/en/uddannelse/kandidat/kandidat-erhvervskandidat/non-eu-admission', 'annual', 'upcoming', 'verified', 10, true, now(), now(), $note$ADDED 2026-10-28 (enrichment batch 20) from the University of Southern Denmark's official 'Scholarships' page fetched the same day (limited number of scholarships for highly qualified non-EU/EEA citizens, only for specific Vejle/Sønderborg programmes; Danish Government Scholarship programme in recognition of overseas students' investment; programme lists for admissions up to and including 2027 - five MSc at Sønderborg (Engineering Physics, Electrical Engineering, Mechanical Engineering, Mechatronics, Software Engineering) and four BSc at Vejle (Artificial Intelligence, Computer Science, Interactive Technology Engineering, Software Engineering) - and from 2028 onwards (four MSc added at Vejle, BSc narrowed to Artificial Intelligence and Computer Science); SU-eligible students excluded; scholarship = full tuition fee waiver for the standard duration (2 years MSc / 3 years BSc), covering 30 ECTS per semester, retention normally requires completing 30 ECTS per semester or funding may be discontinued; bachelor route: no separate application, apply by 15 March, highest uniTEST scorers invited to early-June online interviews (one interview only; brief maths questions and motivation talk, no specific preparation; invitation late May at short notice); master route: no separate application, apply by 1 February even with a Danish residence permit, complete documentation at submission (deposit fee receipt, official bachelor's transcripts/diploma in EN/DA/SV/NO with grades and ECTS, verified course descriptions, self-assessment form where relevant, proof of English; uploads only, no email documents), eligible programme must be the highest priority, selection on bachelor's GPA plus online interview (invitations after 15 February, interviews normally 19-27 February, a few technical questions)). Note honestly: an older SDU master's page once described a DKK 3,000/month living grant for two Sønderborg engineering MSc programmes; the current canonical scholarships page (which also maps out the 2028 programme lists) describes the scholarship as the fee waiver alone, so no living grant is recorded here. Award stored as NULL (DKK, 'year', 'variable'): a full waiver whose krone value follows each programme's fee. deadline_date 2027-02-01 is the next master's consideration gate (the 15 March 2027 bachelor gate is in the deadline text and rounds JSON); status 'upcoming' because the application windows were not shown as already open on the verification date. min_gpa/min_ielts NULL. university_id intentionally NULL: no University of Southern Denmark record exists in the universities table yet - create/backlink recorded as a future task; no university_scholarships row. A dedicated verified source was inserted for the SDU scholarships page. The scheme is SDU's administration of the same Danish state scholarship family as records 413 (Aarhus) and 972 (Roskilde), with its own campus-bound programme lists and test/interview selection.$note$, NULL, NULL, 'DKK', 'year', 'variable', NULL, 'Full tuition fee waiver for the standard duration (2 years MSc / 3 years BSc), covering 30 ECTS per semester, on the named Sønderborg/Vejle programmes only; keep it by completing 30 ECTS per semester. No separate application (bachelor selection via uniTEST + interview; master selection via bachelor GPA + interview).', 'The tuition fee is waived in full for the standard programme duration (30 ECTS per semester covered; extra credits in a semester are not); living expenses are not part of the current scheme.', 'No scholarship-level IELTS figure; proof of English proficiency is one of the mandatory admission documents per programme rules.', $j$["Admission application for a listed programme by the consideration deadline - no separate scholarship application", "Master's applicants (by 1 February): application deposit fee receipt; official bachelor's transcripts and diploma in English/Danish/Swedish/Norwegian with grades and ECTS per course; verified course descriptions; self-assessment form if relevant; proof of English proficiency - all uploaded at submission (no email documents accepted)", "Bachelor's applicants (by 15 March): admission application plus the online uniTEST; top scorers then attend an online interview in early June"]$j$, NULL, NULL, $json$[{"route": "Master's (Sønderborg)", "apply_by": "2027-02-01", "interviews": "February 19-27", "status": "upcoming"}, {"route": "Bachelor's (Vejle)", "apply_by": "2027-03-15", "interviews": "early June", "status": "upcoming"}, {"pattern": "Annual: no separate application; master's gate 1 February (GPA + February interviews), bachelor's gate 15 March (uniTEST + June interviews); programme lists fixed per intake period (2028 lists already published)"}]$json$);

